// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash) public {
        address actor = address(0x1000);
        vm.deal(actor, 2 ether);

        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(hash) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
